using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;
using System.Reflection;
using System.Diagnostics;
using AiCreditDesktop;

internal static class VideoCardsFixture {
 static int tests,failed;
 static void Check(bool ok,string name){tests++;if(!ok)failed++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static Dictionary<string,object> Row(string p,string status){return new Dictionary<string,object>{{"platform",p},{"accountId",p},{"label",p},{"edition",p=="kling"||p=="hailuo"?"global":"cn"},{"value",p=="jimeng"?125:60},{"unit","积分"},{"checkedAt",DateTimeOffset.UtcNow.ToString("o")},{"capabilities",new Dictionary<string,object>{{"checkin",true}}},{"dailyCheckin",new Dictionary<string,object>{{"status",status},{"known",status!="unknown"},{"todayCheckedIn",status=="claimed"?(object)true:null},{"credits",status=="observed"?0:30}}}};}
 [STAThread] static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string output=args[0];Directory.CreateDirectory(output);string[] names={"vidu","pixverse","jimeng","kling","xiaoyunque","hailuo","liblib"};
  if(args.Length>1){var input=Json.Object(File.ReadAllText(args[1]));var rows=((System.Collections.IEnumerable)input["accounts"]).Cast<object>().Select(x=>x as Dictionary<string,object>).Where(x=>x!=null).ToArray();using(var panel=new FlowLayoutPanel()){panel.Size=new Size(1440,1020);panel.BackColor=Theme.Background;panel.Padding=new Padding(8);foreach(string p in names){var row=rows.Single(x=>Json.Get(x,"platform")==p);var card=new CreditCard(row,Theme.Accent,()=>{},()=>{});card.Size=new Size(460,CreditCard.UniformHeight);panel.Controls.Add(card);card.CreateControl();Console.WriteLine("LIVE "+p+" badge="+PlatformPresentation.HealthBadge(row)+" url="+VideoNavigationUrl(row));}panel.CreateControl();panel.PerformLayout();using(var bmp=new Bitmap(panel.Width,panel.Height)){panel.DrawToBitmap(bmp,panel.ClientRectangle);bmp.Save(Path.Combine(output,"LIVE-VIDEO-CARDS.png"));}}Console.WriteLine("LIVE_VIDEO_CARDS accounts="+rows.Length+" liveData=true grants=0 exit=0");return 0;}
  using(var panel=new FlowLayoutPanel()){panel.Size=new Size(1440,1020);panel.BackColor=Theme.Background;panel.Padding=new Padding(8);
   foreach(string p in names){var data=Row(p,p=="vidu"?"observed":p=="kling"||p=="hailuo"?"not_available":"claimed");var card=new CreditCard(data,Theme.Accent,()=>{},()=>{});card.Size=new Size(460,CreditCard.UniformHeight);panel.Controls.Add(card);card.CreateControl();var buttons=card.Controls.OfType<Button>().OrderBy(b=>b.Left).ToArray();Check(buttons.Select(b=>b.Text).SequenceEqual(new[]{"重新核验","进入","额度明细"}),p+" three ordered actions");Check(buttons.All(b=>b.Left>=0&&b.Right<=card.Width&&b.Top>=0&&b.Bottom<=card.Height),p+" bounded actions");Check(PlatformLogoCache.Get(p)!=null,p+" official local logo loads");Check(PlatformPresentation.Name(p)!=p,p+" localized platform name");Check(!PlatformPresentation.HealthBadge(data).Contains("待领取"),p+" verified or ineligible is not claimable");Check(card.AccessibleName.Contains(PlatformPresentation.HealthBadge(data)),p+" accessible status matches painted card");}
   panel.CreateControl();panel.PerformLayout();using(var bmp=new Bitmap(panel.Width,panel.Height)){panel.DrawToBitmap(bmp,panel.ClientRectangle);bmp.Save(Path.Combine(output,"VIDEO-CARDS.png"));}
  }
  Check(PlatformPresentation.HealthBadge(Row("vidu","observed")).Contains("0积分"),"official zero receipt is visibly distinguished");Check(PlatformPresentation.HealthBadge(Row("kling","not_available")).Contains("资格"),"ineligible is not mislabeled signed");Check(PlatformPresentation.HealthBadge(Row("hailuo","not_available")).Contains("每日"),"one-time trial is not daily claim");Check(PlatformPresentation.HealthBadge(Row("pixverse","unknown")).Contains("待核验"),"unknown is not pending claim");Check(PlatformPresentation.HealthBadge(Row("pixverse","claimable"))=="待领取","explicit eligible state remains claimable");Check(PlatformPresentation.HealthBadge(Row("jimeng","claimed"))=="今日已签到","manual same-day official receipt shows signed");var stale=Row("jimeng","claimed");stale["stale"]=true;Check(PlatformPresentation.HealthBadge(stale).Contains("待核验"),"stale receipt not green");
  var nav=typeof(CreditCard).Assembly.GetType("AiCreditDesktop.VideoNavigation");Check(nav!=null,"shared Edge navigation exists");if(nav!=null){var build=nav.GetMethod("Build",BindingFlags.Static|BindingFlags.NonPublic);var launch=nav.GetField("Launch",BindingFlags.Static|BindingFlags.NonPublic);foreach(string p in names){var row=Row(p,"claimed");var psi=(ProcessStartInfo)build.Invoke(null,new object[]{row});Check(psi.FileName.IndexOf("edge",StringComparison.OrdinalIgnoreCase)>=0,p+" explicitly targets Edge");Check((psi.FileName+psi.Arguments).Contains("https://"),p+" https navigation");}int launched=0;launch.SetValue(null,new Action<ProcessStartInfo>(psi=>{launched++;}));using(var c=new CreditCard(Row("vidu","claimed"),Theme.Accent,()=>{},()=>{})){c.Size=new Size(460,CreditCard.UniformHeight);c.CreateControl();c.Controls.OfType<Button>().Single(b=>b.Text=="进入").PerformClick();}Check(launched==1,"actual entrance click dispatches exactly once without refresh or claim");var cn=Row("kling","claimed");cn["websiteUrl"]="https://klingai.kuaishou.com/";var cnPsi=(ProcessStartInfo)build.Invoke(null,new object[]{cn});Check((cnPsi.FileName+cnPsi.Arguments).Contains("klingai.kuaishou.com"),"verified CN origin overrides global account default");cn["websiteUrl"]="https://example.invalid/";var fallback=(ProcessStartInfo)build.Invoke(null,new object[]{cn});Check(!(fallback.FileName+fallback.Arguments).Contains("example.invalid"),"untrusted URL cannot replace official target");}
  using(var c=new CreditCard(new Dictionary<string,object>{{"platform","workbuddy"}},Theme.Accent,()=>{},()=>{})){Check(c.Controls.OfType<Button>().Count()==2,"other platforms retain two existing actions");}
  var global=Row("kling","claimed");global.Remove("edition");global["websiteUrl"]="https://klingai.com";Check(PlatformPresentation.Subtitle(global).Contains("国际站"),"actual global origin controls region even when summary has no edition");
  Console.WriteLine("VIDEO_CARDS_NATIVE tests="+tests+" failures="+failed+" exit="+(failed==0?0:1));return failed==0?0:1;
 }
 static string VideoNavigationUrl(Dictionary<string,object> row){var nav=typeof(CreditCard).Assembly.GetType("AiCreditDesktop.VideoNavigation");if(nav==null)return "MISSING";return (string)nav.GetMethod("Url",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{row});}
}
